from ..device_pool import DeviceActivePools
from ..exceptions import UnknownDevicePoolPackage


class DemoDeviceActivePool(DeviceActivePools):
    """Demo Device Active Pool."""
    DEVICE_POOL_TYPE = "DEVICE_POOLS"

    def __init__(self):
        """Basic initialization."""
        super(DemoDeviceActivePool, self).__init__(self.DEVICE_POOL_TYPE)

    def convert_pool_type_2_pool_class_fullname(self, pool_type):
        """
        Encapsulate convention how to produce full package.module.class name for given DevicePool type
        :param device_pool_type: DevicePool type
        :return: full package.module.class name
        """
        class_name = pool_type
        module_name = class_name.lower()
        (device_type_name, device_str, rest) = module_name.partition("device")
        if device_str and rest:
            package_name = f"ute_common_abstract_core.device.{device_type_name}"
            pool_class_fullname = f"{package_name}.{module_name}.{class_name}"
            return pool_class_fullname
        raise UnknownDevicePoolPackage(module_name, class_name)
